import requests
import attrs
from functools import wraps
from datetime import datetime, timezone
import math
import warnings
from urllib3.exceptions import InsecureRequestWarning

from taf.hw.hp.redfish.exceptions import AuthorizationFailed


@attrs.define(eq=True, frozen=True)
class TokenDetails(object):
    access_token: str = attrs.field()
    access_token_expires_in: float = attrs.field()
    session_id: str = attrs.field()


class Authorization(object):
    @staticmethod
    def get_access_token_details(host, port, username, password):
        token_url = f'https://{host}:{port}/redfish/v1/SessionService/Sessions'
        request_data = {
            "UserName": username,
            "Password": password
        }
        try:
            with warnings.catch_warnings():
                warnings.simplefilter("ignore", InsecureRequestWarning)
                token_response = Authorization._get_token_response(token_url, request_data)
            current_timestamp = datetime.now().timestamp()
            expire_date = token_response.json()['Oem']['Hpe']['UserExpires']
            expire_time = datetime.strptime(expire_date, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
            login_date = token_response.json()['Oem']['Hpe']['LoginTime']
            login_time = datetime.strptime(login_date, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
            seconds_difference = math.ceil((expire_time - login_time).total_seconds())
            expired_seconds = current_timestamp + seconds_difference

            return TokenDetails(
                access_token=token_response.headers.get("X-Auth-Token"),
                access_token_expires_in=expired_seconds,
                session_id=token_response.json().get("Id")
            )
        except Exception as e:
            raise AuthorizationFailed(str(e))

    @staticmethod
    def _get_token_response(url, request_data):
        response = requests.post(url, json=request_data, verify=False)
        response.raise_for_status()

        return response

    @staticmethod
    def close_session(conn_details, token_details):
        url = f'https://{conn_details.host}/redfish/v1/SessionService/Sessions/{token_details.session_id}'
        headers = {"X-Auth-Token": token_details.access_token}
        with warnings.catch_warnings():
            warnings.simplefilter("ignore", InsecureRequestWarning)
            response = requests.delete(url, headers=headers, verify=False)
        response.raise_for_status()


class TokenProvider(object):

    @staticmethod
    def provide_access_token(func):
        @wraps(func)
        def wrapper(redfish_instance, *args, **kwargs):
            if datetime.now().timestamp() >= redfish_instance.token_details.access_token_expires_in:
                token_details = Authorization.get_access_token_details(redfish_instance.conn_details.host,
                                                                       redfish_instance.conn_details.port,
                                                                       redfish_instance.conn_details.username,
                                                                       redfish_instance.conn_details.password)

                redfish_instance.token_details = token_details

                for attribute in redfish_instance.__dict__.keys():
                    attr_value = getattr(redfish_instance, attribute)
                    if hasattr(attr_value, 'api_client'):
                        attr_value.api_client.token = token_details.access_token

            return func(redfish_instance, *args, **kwargs)

        return wrapper
